def abbr(S: Any, max: Any, ellipsis: Any = '...') -> object {
    if (S is None) {
        return '???';
    }
    if (len(S) > max) {
        return ((ellipsis and (S[:(max - len(ellipsis))] + ellipsis)) or S[:max]);
    }
    return S;
}

