"""Return the internal pressure [Pa] that induces a stress, sig, in a thin wall pipe
    of thickness t - PD8010-2 Equation (3).

    :param float t: Wall thickness [m]
    :param float D_o: Outside diamter [m]
    :param float P_o: External pressure [Pa]
    :param float sig: Stress [Pa]
    """
def hoop_pressure_thin(t: Any, D_o: Any, P_o: Any, sig: Any) -> object {
    return (((sig * 2 * t) / D_o) + P_o);
}

"""Either takes the last element or it doesn't.

    This algorithm takes exponential time."""
def _recursive_01_knapsack_aux(capacity: int, w: list, v: list, value: int) -> int {
    if (capacity == 0) {
        return 0;
    }
    if ((len(w) > 0) and (len(v) > 0)) {
        if (w[-1] > capacity) {
            value = _recursive_01_knapsack_aux(capacity, w[:-1], v[:-1], value);
        } else {
            value = max(
                (
                    v[-1]
                    + _recursive_01_knapsack_aux(
                        (capacity - w[-1]), w[:-1], v[:-1], value
                    )
                ),
                _recursive_01_knapsack_aux(capacity, w[:-1], v[:-1], value)
            );
        }
    }
    return value;
}
